package com.nigson.commerce.promotion;
import java.util.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.*;
import com.nigson.shared.observability.WireContext;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import tools.jackson.databind.JsonNode;
@RestController
@ConditionalOnProperty(name="NIGSON_SECURITY_ENABLED",havingValue="true")
public final class PromotionController {
 private final PromotionService service;public PromotionController(PromotionService service){this.service=service;}
 private ActorAssertion.Actor actor(HttpServletRequest r)throws java.io.IOException{var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated())throw new Problem.Failure(ProblemCode.AUTH_REQUIRED);if(!(a.getPrincipal() instanceof ActorAssertion.Actor actor))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return actor;}
 private void query(HttpServletRequest r,Set<String> allowed,boolean body)throws java.io.IOException{if(!allowed.containsAll(r.getParameterMap().keySet()))throw ApiValues.invalid();for(var e:r.getParameterMap().entrySet())if(e.getValue().length!=1||e.getValue()[0].length()>100)throw ApiValues.invalid();if(body&&r.getInputStream().read()!=-1)throw ApiValues.invalid();}
 private String header(HttpServletRequest r,String name){var v=Collections.list(r.getHeaders(name));if(v.size()!=1)throw ApiValues.invalid();return v.getFirst();}
 private UUID correlation(){return WireContext.current()==null?WireContext.correlation(null):WireContext.current().correlationId;}
 private PromotionValues.Query page(Map<String,String> q){int p=number(q.get("page"),0,0,10000000),s=number(q.get("size"),20,1,100);return new PromotionValues.Query(p,s,q.getOrDefault("sort","createdAt,desc"));}
 private Map<String,String> params(HttpServletRequest r)throws java.io.IOException{query(r,Set.of("page","size","sort"),true);var m=new HashMap<String,String>();for(String k:r.getParameterMap().keySet())m.put(k,r.getParameter(k));return m;}
 private int number(String s,int fallback,int min,int max){if(s==null)return fallback;if(!s.matches("0|[1-9][0-9]{0,8}"))throw ApiValues.invalid();try{int n=Integer.parseInt(s);if(n<min||n>max)throw ApiValues.invalid();return n;}catch(NumberFormatException x){throw ApiValues.invalid();}}
 private <T>ResponseEntity<T> created(T value){return ResponseEntity.status(201).header("Cache-Control","no-store").header("ETag","\""+version(value)+"\"").body(value);}
 private long version(Object v){if(v instanceof PromotionValues.Rule x)return x.version();if(v instanceof PromotionValues.Coupon x)return x.version();if(v instanceof PromotionValues.Campaign x)return x.version();return 0;}
 @GetMapping(value="/api/v1/staff/promotion-rules",produces="application/json")public ResponseEntity<PromotionValues.Page<PromotionValues.Rule>> rules(HttpServletRequest r)throws java.io.IOException{return ResponseEntity.ok().header("Cache-Control","no-store").body(service.rules(actor(r),page(params(r))));}
 @PostMapping(value="/api/v1/staff/promotion-rules",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Rule> createRule(HttpServletRequest r,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);return created(service.createRule(actor(r),PromotionValues.rule(b,true),header(r,"Idempotency-Key"),correlation()));}
 @PostMapping(value="/api/v1/staff/promotion-rules/{id}/revisions",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Rule> revise(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);return created(service.revise(actor(r),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),PromotionValues.rule(b,false),header(r,"Idempotency-Key"),correlation()));}
 @PostMapping(value="/api/v1/staff/promotion-rules/{id}/activation",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Rule> activate(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);var value=service.activate(actor(r),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),b,header(r,"Idempotency-Key"),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").header("ETag","\""+value.version()+"\"").body(value);}
 @GetMapping(value="/api/v1/staff/coupons",produces="application/json")public ResponseEntity<PromotionValues.Page<PromotionValues.Coupon>> coupons(HttpServletRequest r)throws java.io.IOException{return ResponseEntity.ok().header("Cache-Control","no-store").body(service.coupons(actor(r),page(params(r))));}
 @PostMapping(value="/api/v1/staff/coupons",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Coupon> coupon(HttpServletRequest r,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);return created(service.createCoupon(actor(r),PromotionValues.coupon(b),header(r,"Idempotency-Key"),correlation()));}
 @PatchMapping(value="/api/v1/staff/coupons/{id}",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Coupon> toggleCoupon(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);var value=service.toggleCoupon(actor(r),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),PromotionValues.couponToggle(b),header(r,"Idempotency-Key"),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").header("ETag","\""+value.version()+"\"").body(value);}
 @GetMapping(value="/api/v1/staff/wheel-campaigns",produces="application/json")public ResponseEntity<PromotionValues.Page<PromotionValues.Campaign>> campaigns(HttpServletRequest r)throws java.io.IOException{return ResponseEntity.ok().header("Cache-Control","no-store").body(service.campaigns(actor(r),page(params(r))));}
 @PostMapping(value="/api/v1/staff/wheel-campaigns",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Campaign> campaign(HttpServletRequest r,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);return created(service.createCampaign(actor(r),PromotionValues.campaign(b),header(r,"Idempotency-Key"),correlation()));}
 @PatchMapping(value="/api/v1/staff/wheel-campaigns/{id}",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Campaign> toggleCampaign(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);var value=service.toggleCampaign(actor(r),ApiValues.uuid(id),ApiValues.version(header(r,"If-Match")),PromotionValues.campaignToggle(b),header(r,"Idempotency-Key"),correlation());return ResponseEntity.ok().header("Cache-Control","no-store").header("ETag","\""+value.version()+"\"").body(value);}
 @PostMapping(value="/api/v1/wheel-campaigns/{id}/draws",consumes="application/json",produces="application/json")public ResponseEntity<PromotionValues.Draw> draw(HttpServletRequest r,@PathVariable String id,@RequestBody JsonNode b)throws java.io.IOException{query(r,Set.of(),false);PromotionValues.exact(b,Set.of("marketId"));var value=service.draw(actor(r),ApiValues.uuid(id),PromotionValues.uuid(b,"marketId"),header(r,"Idempotency-Key"),correlation());return created(value);}
}
